using System.Text.Json.Nodes;

namespace SlopGarden.Contracts;

/// <summary>
/// The desired configuration of one device, generated by the server and pushed over the hub.
/// The client caches the latest document on disk so it keeps running approved sensors,
/// schedules and safety limits while offline.
/// </summary>
public sealed record DeviceConfigDocument(
    int Version,
    Guid DeviceId,
    string DeviceName,
    DateTimeOffset GeneratedAt,
    string TimeZoneId,
    IReadOnlyList<SensorConfig> Sensors,
    IReadOnlyList<ActuatorConfig> Actuators,
    IReadOnlyList<CameraConfig> Cameras,
    IReadOnlyList<ScheduleConfig> Schedules,
    EmergencyStopState EmergencyStop,
    ClientSettings Settings,
    IReadOnlyList<TrustedPluginKey> TrustedPluginKeys);

public sealed record ClientSettings(int ReadingBatchSeconds = 5, int HeartbeatSeconds = 30, int OfflineBufferMaxRows = 500_000)
{
    public static readonly ClientSettings Default = new();
}

public sealed record SensorConfig(
    Guid Id,
    string Name,
    string PluginId,
    JsonObject Settings,
    int ReadIntervalSec,
    bool Enabled,
    IReadOnlyList<ChannelConfig> Channels);

public sealed record ChannelConfig(
    Guid Id,
    string Key,
    string Metric,
    string Unit,
    CalibrationConfig? Calibration,
    double? MinValid,
    double? MaxValid);

/// <summary>
/// Calibration applied on the client: <c>none</c>, <c>linear</c> (value = raw * Scale + Offset),
/// <c>two_point</c> (maps RawLow→ValueLow and RawHigh→ValueHigh, e.g. dry/wet soil probe), or
/// <c>polynomial</c> (value = Σ Coefficients[i] * raw^i).
/// </summary>
public sealed record CalibrationConfig(
    string Type,
    double? Scale = null,
    double? Offset = null,
    double? RawLow = null,
    double? ValueLow = null,
    double? RawHigh = null,
    double? ValueHigh = null,
    IReadOnlyList<double>? Coefficients = null,
    bool Clamp = false);

public sealed record ActuatorConfig(
    Guid Id,
    string Name,
    string Kind,
    string PluginId,
    JsonObject Settings,
    bool Enabled,
    string FailsafeState,
    double? FlowRateMlPerMin,
    ActuatorSafety Safety);

/// <summary>Effective (most restrictive) safety limits the server resolved for one actuator.
/// The client enforces them locally and cannot be overridden by commands.</summary>
public sealed record ActuatorSafety(
    int? MaxRunSeconds,
    int? MaxDailyRunSeconds,
    int? MinSecondsBetweenRuns,
    double? MaxDailyAmountMl,
    IReadOnlyList<SafetyInterlock> Interlocks)
{
    public static readonly ActuatorSafety None = new(null, null, null, null, []);
}

/// <summary>Blocks (and stops) the actuator while <c>channel {Operator} Threshold</c> is true,
/// e.g. tank level lt 15 (no pumping when tank is low) or air temperature gt 32 (heater/light cutoff).</summary>
public sealed record SafetyInterlock(string LimitType, Guid ChannelId, string Operator, double Threshold, string Description)
{
    public bool IsTripped(double value) => Operator switch
    {
        "lt" => value < Threshold,
        "lte" => value <= Threshold,
        "gt" => value > Threshold,
        "gte" => value >= Threshold,
        _ => false,
    };
}

public sealed record CameraConfig(
    Guid Id,
    string Name,
    string PluginId,
    JsonObject Settings,
    int CaptureWidth,
    int CaptureHeight,
    int FrameIntervalSec,
    bool Enabled);

/// <summary>An approved actuator schedule. Runs on the client (so it keeps working offline).
/// <c>Cron</c> is a standard 5-field cron expression evaluated in <c>TimeZoneId</c>.</summary>
public sealed record ScheduleConfig(
    Guid Id,
    string Name,
    Guid ActuatorId,
    string Cron,
    string TimeZoneId,
    int DurationSec,
    double? AmountMl,
    bool Enabled);
